package io.aegiswire.policy;
import io.aegiswire.core.ScanContext; import io.aegiswire.model.*; import java.util.regex.*;
public class Condition { private final String field, op, value; private final boolean negated; public Condition(String f,String o,String v,boolean n){field=f;op=o;value=v;negated=n;} public boolean matches(ScanContext c){ boolean r=eval(c); return negated?!r:r; } private boolean eval(ScanContext c){ String actual=c.get(field); if("exists".equals(op)) return actual!=null; if(actual==null)return false; if("equals".equals(op)) return actual.equals(value); if("contains".equals(op)) return actual.toLowerCase().contains(value.toLowerCase()); if("prefix".equals(op)) return actual.startsWith(value); if("suffix".equals(op)) return actual.endsWith(value); if("matches".equals(op)) return Pattern.compile(value).matcher(actual).find(); if("matches-cidr".equals(op)) return CidrRange.parse(value).contains(IpAddress.parse(actual)); return false; } }
